export function getContextualIntentSuggestions(skill:string,max=3):IntentSuggestion[]{const normalized=skill.trim().toLowerCase();const category=getEconomicCategory(normalized)||'';const key=CONTEXTUAL_SUGGESTIONS[normalized]?normalized:(CATEGORY_SUGGESTION_KEY[category]||'');return (CONTEXTUAL_SUGGESTIONS[key]||[]).slice(0,Math.max(0,max)).map(item=>({...item}));}
function normalize(row:any):SkillFlow|null{if(!row)return null;const skill=String(row.skill||'').trim();if(!skill)return null;const category=getEconomicCategory(skill);const mode=String(row.flow_mode||EXPLICIT_SKILL_FLOW_DEFINITIONS[skill]?.mode||'economic') as SkillFlow['mode'];return{skill,question_set:String(row.question_set||'').trim(),post_match_action:String(row.post_match_action||'').trim(),payment_model:String(row.payment_model||'').trim(),fulfillment_instructions:String(row.fulfillment_instructions||'').trim(),capabilities:getSkillCapabilities(skill),category:category||undefined,mode:['economic','information','safety','coordination'].includes(mode||'')?mode:'economic',requirements:getSkillRequirements(skill)};}








