function seedCanonicalSkillFlows(db:any):void{for(const [skill,definition] of Object.entries(EXPLICIT_SKILL_FLOW_DEFINITIONS)){db.run(`INSERT INTO skill_flows(skill,question_set,post_match_action,payment_model,fulfillment_instructions,flow_mode) VALUES(?,?,?,?,?,?) ON CONFLICT(skill) DO UPDATE SET question_set=excluded.question_set,post_match_action=excluded.post_match_action,payment_model=excluded.payment_model,fulfillment_instructions=excluded.fulfillment_instructions,flow_mode=excluded.flow_mode`,[skill,JSON.stringify(definition.questions),definition.action,definition.payment,definition.fulfillment,definition.mode]);}}
export async function getSkillFlow(skill:string):Promise<SkillFlow|null>{const name=skill.trim();if(!name)return null;const db=await getDb();seedCanonicalSkillFlows(db);const s=db.prepare(`SELECT skill,question_set,post_match_action,payment_model,fulfillment_instructions,flow_mode FROM skill_flows WHERE skill=? LIMIT 1`);s.bind([name]);const r=s.step()?normalize(s.getAsObject()):null;s.free();return r;}
export async function auditSkillFlows(){const db=await getDb();const s=db.prepare(`SELECT skill,question_set,post_match_action,payment_model,fulfillment_instructions FROM skill_flows ORDER BY skill`);const invalid:string[]=[];let total=0,valid=0;while(s.step()){total++;const row=s.getAsObject();const f=normalize(row);if(!f||!f.question_set||!f.post_match_action||!f.payment_model||!f.fulfillment_instructions||!f.category)invalid.push(f?.skill||String(row.skill||'unknown'));else valid++;}s.free();return{total,valid,invalid};}
export function auditEconomicTaxonomy(){const skills=Object.keys(CATEGORY_BY_SKILL);const categorySet=new Set<string>(ECONOMIC_CATEGORIES);return{categories:ECONOMIC_CATEGORIES.length,skills:skills.length,unmapped:skills.filter(s=>!categorySet.has(CATEGORY_BY_SKILL[s]))};}
export interface EconomicRequest { id:string; phone:string; skill:string; category:string; status:EconomicRequestStatus; requirements:Record<string,unknown>; capabilities:EconomicCapability[]; providerPhone?:string|null; quote?:Record<string,unknown>|null; fulfillment?:Record<string,unknown>|null; conversationId?:string|null; createdAt?:string; updatedAt?:string; }
async function ensureEconomicRequestsTable(){const db=await getDb();db.run(`CREATE TABLE IF NOT EXISTS economic_requests (id TEXT PRIMARY KEY, phone TEXT NOT NULL, skill TEXT NOT NULL, category TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'requested', requirements_json TEXT NOT NULL DEFAULT '{}', capabilities_json TEXT NOT NULL DEFAULT '[]', provider_phone TEXT, quote_json TEXT, fulfillment_json TEXT, conversation_id TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP)`);const columns=(db.exec('PRAGMA table_info(economic_requests)')?.[0]?.values||[]).map((row:any)=>String(row[1]||''));if(!columns.includes('conversation_id'))db.run('ALTER TABLE economic_requests ADD COLUMN conversation_id TEXT');db.run(`CREATE INDEX IF NOT EXISTS idx_economic_requests_phone_status ON economic_requests(phone,status)`);return db;}
function rowToEconomicRequest(r:any):EconomicRequest{return{id:String(r.id),phone:String(r.phone),skill:String(r.skill),category:String(r.category),status:String(r.status) as EconomicRequestStatus,requirements:JSON.parse(String(r.requirements_json||'{}')),capabilities:JSON.parse(String(r.capabilities_json||'[]')),providerPhone:r.provider_phone?String(r.provider_phone):null,quote:r.quote_json?JSON.parse(String(r.quote_json)):null,fulfillment:r.fulfillment_json?JSON.parse(String(r.fulfillment_json)):null,conversationId:r.conversation_id?String(r.conversation_id):null,createdAt:r.created_at?String(r.created_at):undefined,updatedAt:r.updated_at?String(r.updated_at):undefined};}
export async function createEconomicRequest(input:{id:string;phone:string;skill:string;requirements:Record<string,unknown>;amount?:number;conversationId?:string}):Promise<EconomicRequest>{const category=getEconomicCategory(input.skill)||'classifieds-marketplace';const capabilities=getSkillCapabilities(input.skill);const db=await ensureEconomicRequestsTable();const conversationId=String(input.conversationId||'').trim().slice(0,160)||null;const s=db.prepare(`INSERT INTO economic_requests(id,phone,skill,category,status,requirements_json,capabilities_json,conversation_id) VALUES(?,?,?,?,'requested',?,?,?)`);s.bind([input.id,input.phone,input.skill,category,JSON.stringify({...input.requirements,amount_minor:input.amount??null}),JSON.stringify(capabilities),conversationId]);s.step();s.free();saveDb();await persistCoordinatorEvent({id:`economic-request:${input.id}:created`,type:'economic_request.state_changed',occurredAt:new Date().toISOString(),producer:'skillFlows',correlationId:`economic_request:${input.id}`,ownerPhone:input.phone.startsWith('anon_')?undefined:input.phone,economicRequestId:input.id,payload:{requestId:input.id,skill:input.skill,category,status:'requested',capabilities,conversationId:conversationId||undefined},sensitivity:input.phone.startsWith('anon_')?'public':'personal',provenance:{source:'canonical_service',sourceId:input.id,evidenceLevel:'persisted_state'},policy:{autonomousAllowed:false,confirmationRequired:'none'},schemaVersion:1});return (await getEconomicRequest(input.id))!;}
export async function getEconomicRequest(id:string):Promise<EconomicRequest|null>{const db=await ensureEconomicRequestsTable();const s=db.prepare(`SELECT * FROM economic_requests WHERE id=? LIMIT 1`);s.bind([id]);const r=s.step()?s.getAsObject():null;s.free();return r?rowToEconomicRequest(r):null;}
/** Owner-scoped request projection for other read-only canonical surfaces such as Agent Briefs. */
export async function listEconomicRequestsForPhone(phone:string,options:{includeClosed?:boolean;limit?:number}={}):Promise<EconomicRequest[]>{const owner=String(phone||'').trim();if(!owner)return[];const db=await ensureEconomicRequestsTable();const limit=Math.max(1,Math.min(100,Math.floor(Number(options.limit)||50)));const closed=options.includeClosed===true;const sql=closed?`SELECT * FROM economic_requests WHERE phone=? ORDER BY updated_at DESC LIMIT ?`:`SELECT * FROM economic_requests WHERE phone=? AND status NOT IN ('completed','fulfilled','cancelled','abandoned') ORDER BY updated_at DESC LIMIT ?`;const s=db.prepare(sql);s.bind([owner,limit]);const rows:EconomicRequest[]=[];while(s.step())rows.push(rowToEconomicRequest(s.getAsObject()));s.free();return rows;}
/** Persist non-lifecycle request context collected through the canonical storefront. */
export async function updateEconomicRequestRequirements(id:string,ownerPhone:string,patch:Record<string,unknown>):Promise<EconomicRequest>{const current=await getEconomicRequest(id);if(!current)throw new Error('Economic request not found');if(current.phone!==ownerPhone)throw new Error('Economic request ownership is required');if(!patch||typeof patch!=='object'||Array.isArray(patch))throw new Error('Requirements patch is required');const safe=Object.fromEntries(Object.entries(patch).filter(([key,value])=>/^[a-zA-Z][a-zA-Z0-9_]{0,63}$/.test(key)&&value!==undefined));const db=await ensureEconomicRequestsTable();const s=db.prepare(`UPDATE economic_requests SET requirements_json=?,updated_at=CURRENT_TIMESTAMP WHERE id=?`);s.bind([JSON.stringify({...current.requirements,...safe}),id]);s.step();s.free();saveDb();await persistCoordinatorEvent({id:`economic-request:${id}:requirements`,type:'economic_request.state_changed',occurredAt:new Date().toISOString(),producer:'skillFlows',correlationId:`economic_request:${id}`,ownerPhone:ownerPhone.startsWith('anon_')?undefined:ownerPhone,economicRequestId:id,payload:{requestId:id,updatedKeys:Object.keys(safe)},sensitivity:ownerPhone.startsWith('anon_')?'public':'personal',provenance:{source:'canonical_service',sourceId:id,evidenceLevel:'persisted_state'},policy:{autonomousAllowed:false,confirmationRequired:'none'},schemaVersion:1});return (await getEconomicRequest(id))!;}
const TRANSITIONS:Record<EconomicRequestStatus,EconomicRequestStatus[]>={requested:['awaiting_match','abandoned','cancelled'],awaiting_match:['partially_matched','matched','abandoned','cancelled'],partially_matched:['matched','quoting','abandoned','cancelled'],matched:['quoting','quoted','reserved','in_fulfillment','abandoned','cancelled'],quoting:['quoted','abandoned','cancelled'],quoted:['awaiting_confirmation','reserved','abandoned','cancelled'],awaiting_confirmation:['reserved','cancelled'],reserved:['payment_pending','paid','cancelled'],payment_pending:['paid','failed','cancelled'],paid:['in_fulfillment','fulfilled','disputed','cancelled'],in_fulfillment:['fulfilled','disputed','failed','cancelled'],fulfilled:['completed','disputed'],completed:['disputed'],cancelled:[],disputed:['completed','failed'],failed:['requested','cancelled'],abandoned:[]};
export function getAllowedEconomicTransitions(status:EconomicRequestStatus):EconomicRequestStatus[]{return [...(TRANSITIONS[status]||[])];}
export async function transitionEconomicRequest(id:string,status:EconomicRequestStatus,patch:{providerPhone?:string;quote?:Record<string,unknown>;fulfillment?:Record<string,unknown>}={}):Promise<EconomicRequest>{const current=await getEconomicRequest(id);if(!current)throw new Error('Economic request not found');if(status!==current.status&&!getAllowedEconomicTransitions(current.status).includes(status))throw new Error(`Invalid economic request transition: ${current.status} -> ${status}`);const db=await ensureEconomicRequestsTable();const s=db.prepare(`UPDATE economic_requests SET status=?,provider_phone=COALESCE(?,provider_phone),quote_json=COALESCE(?,quote_json),fulfillment_json=COALESCE(?,fulfillment_json),updated_at=CURRENT_TIMESTAMP WHERE id=?`);s.bind([status,patch.providerPhone??null,patch.quote?JSON.stringify(patch.quote):null,patch.fulfillment?JSON.stringify(patch.fulfillment):null,id]);s.step();s.free();
  try {
    const logStmt = db.prepare(`INSERT INTO audit_logs(action, details) VALUES(?, ?)`);
    logStmt.bind(['economic_request_transition', JSON.stringify({ requestId: id, phone: current.phone, skill: current.skill, fromStatus: current.status, toStatus: status })]);
    logStmt.step();
    logStmt.free();
    saveDb();
  } catch {}
  await persistCoordinatorEvent({id:`economic-request:${id}:transition:${status}:${Date.now()}`,type:'economic_request.state_changed',occurredAt:new Date().toISOString(),producer:'skillFlows',correlationId:`economic_request:${id}`,ownerPhone:current.phone.startsWith('anon_')?undefined:current.phone,economicRequestId:id,payload:{requestId:id,fromStatus:current.status,toStatus:status,providerPhone:patch.providerPhone||current.providerPhone||undefined,hasQuote:Boolean(patch.quote||current.quote),hasFulfillment:Boolean(patch.fulfillment||current.fulfillment)},sensitivity:current.phone.startsWith('anon_')?'public':'personal',provenance:{source:'canonical_service',sourceId:id,evidenceLevel:'persisted_state'},policy:{autonomousAllowed:false,confirmationRequired:'none'},schemaVersion:1});
  return (await getEconomicRequest(id))!;}

export async function updateEconomicRequestStatus(id:string,status:EconomicRequestStatus,patch:{providerId?:string;quote?:Record<string,unknown>;fulfillment?:Record<string,unknown>}={}):Promise<EconomicRequest>{return transitionEconomicRequest(id,status,{providerPhone:patch.providerId,quote:patch.quote,fulfillment:patch.fulfillment});}
